use std::sync::{Arc, Mutex};
use std::thread;

static mut ACC: i64 = 0;

fn w2() {
    let x: i64 = 1;
    let _y: i64 = x + 1;
}

fn w1(m: &Mutex<i64>) {
    {
        let mut acc = m.lock().unwrap();
        w2();
        let c: i64 = *acc;
        let c2: i64 = c + 1;
        *acc = c2;
    }
}

fn main() {
    let m = Arc::new(Mutex::new(0i64));

    let m1 = Arc::clone(&m);
    let h1 = thread::spawn(move || {
        w1(&m1);
    });

    let m2 = Arc::clone(&m);
    let h2 = thread::spawn(move || {
        w1(&m2);
    });

    h1.join().unwrap();
    h2.join().unwrap();

    let done = {
        let acc = m.lock().unwrap();
        *acc
    };

    println!("DONE done={}", done);
}
